class Solution {
public:
    long long minimumOperations(vector<int>& nums, vector<int>& target) {
        long long ans = 0;
        int prev = 0;
        for (size_t i = 0; i < nums.size(); i++) {
            int d = target[i] - nums[i];
            if (d > prev) ans += d - prev;
            prev = d;
        }
        return ans;
    }
};

