class Solution:
    def minimumOperations(self, nums: list[int], target: list[int]) -> int:
        d = [b - a for a, b in zip(nums, target)]
        ops = 0
        while any(d):
            ops += 1
            i = 0
            while i < len(d):
                if d[i]:
                    s = 1 if d[i] > 0 else -1
                    while i < len(d) and d[i] * s > 0:
                        d[i] -= s
                        i += 1
                else:
                    i += 1
        return ops

