class Solution {
public:
    long long minimumOperations(vector<int>& nums, vector<int>& target) {
        int n = nums.size();
        vector<long long> d(n);
        for (int i = 0; i < n; i++) d[i] = (long long)target[i] - nums[i];
        long long ops = 0;
        bool moved = true;
        while (moved) {
            moved = false;
            int i = 0;
            while (i < n) {
                if (d[i] != 0) {
                    moved = true; ops++;
                    long long s = d[i] > 0 ? 1 : -1;
                    while (i < n && d[i] * s > 0) { d[i] -= s; i++; }
                } else i++;
            }
        }
        return ops;
    }
};

