var minimumOperations = function(nums, target) {
    const d = nums.map((a, i) => target[i] - a);
    let ops = 0;
    while (d.some(v => v !== 0)) {
        ops++;
        let i = 0;
        while (i < d.length) {
            if (d[i] !== 0) {
                const s = d[i] > 0 ? 1 : -1;
                while (i < d.length && d[i] * s > 0) { d[i] -= s; i++; }
            } else i++;
        }
    }
    return ops;
};
